style.css:
/* Pink Cloud — SoundCloud */

:root {
  /* change les couleurs ici */
  --my-bg: #fff4f7;
  --my-card: #ffffff;
  --my-pink: #f3b8cc;
  --my-accent: #e89ab7;
  --my-text: #684b59;
  --my-muted: #aa8998;
}

/* fond général */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* liens */
a {
  color: var(--my-accent) !important;
}

/* sélection de texte */
::selection {
  background: var(--my-pink) !important;
  color: #684b59 !important;
}

/* barres de défilement */
* {
  scrollbar-color: var(--my-pink) var(--my-bg);
}
